  ('0f14dc42-adca-54cd-b5b0-dc3a60af4b1d', null, (select id from public.skills where slug = 'punctuation-basics'), null, 'hard',
   $q$Coach Okafor's sentence is split by the speaker tag. Which version is punctuated correctly?$q$, $q$[{"text":"\"If it rains\" said Coach Okafor, \"we will practice in the gym.\"","is_correct":false,"misconception_token":"missing-comma-inside-quote"},{"text":"\"If it rains,\" said Coach Okafor, \"we will practice in the gym.\"","is_correct":true},{"text":"\"If it rains,\" said Coach Okafor, \"We will practice in the gym.\"","is_correct":false,"misconception_token":"capitalizes-continued-quote"},{"text":"\"If it rains,\" said Coach Okafor \"we will practice in the gym.\"","is_correct":false,"misconception_token":"missing-comma-after-tag"}]$q$::jsonb, $q$"If it rains," said Coach Okafor, "we will practice in the gym."$q$, $q$Commas go inside the first quotation and after the speaker tag, and the second part starts with a lowercase letter because it continues the same sentence. Capitalizing "We" treats it as a new sentence, which it is not.$q$, 'draft', null)
