  ('fdb0cfa6-3daa-5741-a6ac-ea8614d9de42', null, (select id from public.skills where slug = 'modifier-placement'), null, 'medium',
   $q$Which sentence contains a dangling modifier?$q$, $q$[{"text":"To win the spelling bee, hours of study were needed.","is_correct":true},{"text":"Jasmine studied for hours to win the spelling bee.","is_correct":false,"misconception_token":"flags-end-position"},{"text":"Studying for hours, Jasmine hoped to win the spelling bee.","is_correct":false,"misconception_token":"flags-participle-opening"},{"text":"To win the spelling bee, Jasmine studied for hours.","is_correct":false,"misconception_token":"flags-correct-opening"}]$q$::jsonb, $q$To win the spelling bee, hours of study were needed.$q$, $q$"To win the spelling bee" needs a person who is trying to win, but the subject is "hours of study," so the phrase has nothing sensible to describe. In the other sentences, Jasmine is the subject and the one doing the action.$q$, 'draft', null)
