  ('1536892c-7ef1-5319-b2da-4b1f3c404b68', null, (select id from public.skills where slug = 'modifier-placement'), null, 'medium',
   $q$The runner set a new school record. Which sentence says this clearly?$q$, $q$[{"text":"Who had set a new school record, Ms. Okafor handed the trophy to the runner.","is_correct":false,"misconception_token":"clause-moved-to-front"},{"text":"Ms. Okafor handed the runner the trophy that had set a new school record.","is_correct":false,"misconception_token":"clause-attached-to-object"},{"text":"Ms. Okafor, who had set a new school record, handed the trophy to the runner.","is_correct":false,"misconception_token":"clause-attached-to-presenter"},{"text":"Ms. Okafor handed the trophy to the runner who had set a new school record.","is_correct":true}]$q$::jsonb, $q$Ms. Okafor handed the trophy to the runner who had set a new school record.$q$, $q$A clause beginning with "who" or "that" describes the noun right before it, so it must follow "runner." Placed after "Ms. Okafor," the clause correctly forms a sentence but says the wrong person set the record.$q$, 'draft', null)
